import crypto from 'crypto';
import DateTimeHandler from './datetime.js';
import { nanoid } from 'nanoid';
import jwt from 'jsonwebtoken';

const ALGORITHM = 'aes-256-cbc';
const HASH_ALGORITHM = 'sha256';
const IV_LENGTH = 16; // bytes
const CHARSETS = 'utf8';
const ENCODER = 'base64';

// get uuid by Genius iQ @20251107
function getUniqueId() {
    return nanoid(11);
}

// encrypt data by Genius iQ @20251107 modified @20260319
function encrypt(plainText, secretKey = 'OhMyGenius!') {
  try {
    const key = deriveKey(secretKey);
    
    const iv = crypto.randomBytes(IV_LENGTH);
    
    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    
    const encrypted = Buffer.concat([
      cipher.update(plainText, CHARSETS),
      cipher.final()
    ]);
    
    const combined = Buffer.concat([iv, encrypted]);
    
    return combined.toString(ENCODER);
  } catch (err) {
    return "";
  }
}

// decrypt data by Genius iQ @20251107 modified @20260319
function decrypt(encryptedText, secretKey = 'OhMyGenius!') {
  try {
    const combined = Buffer.from(encryptedText, ENCODER);
    
    const iv = combined.subarray(0, IV_LENGTH);
    const ciphertext = combined.subarray(IV_LENGTH);
    
    const key = deriveKey(secretKey);
    
    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    
    const decrypted = Buffer.concat([
      decipher.update(ciphertext),
      decipher.final()
    ]);
    
    return decrypted.toString(CHARSETS);
  } catch (err) {
    return "";
  }
}

// APIs token authorization by Genius iQ @20251108 modified @20251114
function generateApiToken(secretKey = 'OhMyGenius!', domain = '*') {
    try {
        const TIME_LIMIT = 15 * 60 * 1000; // 15 minutes, 24 * 60 * 60 * 1000 = 1 day
        const expireTime = Date.now() + TIME_LIMIT;
        const domainUse = domain || '*';
        const uuid = getUniqueId();

        const tokenBase = domainUse + uuid + expireTime + secretKey;

        const tokenHash = crypto.createHash('sha256')
            .update(tokenBase)
            .digest('hex');

        const domainHex = Buffer.from(domainUse).toString('hex');
        const uuidHex = Buffer.from(uuid).toString('hex');
        const expireHex = expireTime.toString(16);

        return {
            token: `${uuidHex}.${tokenHash}.${expireHex}.${domainHex}`,
            expireAt: DateTimeHandler.formatTokenExpireTime(expireTime),
        };
    } catch (err) {
        return null;
    }
}

function verifyApiToken(token, secretKey = 'OhMyGenius!', domain = '*') {
    try {
        const parts = token.split('.');

        if (parts.length !== 4) {
            return { status: 400, message: 'Invalid Token Format!' };
        }

        const [uuidHex, tokenHex, expireHex, domainHex] = parts;

        const domainUse = Buffer.from(domainHex, 'hex').toString('utf8');
        const uuid = Buffer.from(uuidHex, 'hex').toString('utf8');
        const expireTime = parseInt(expireHex, 16);

        if (Date.now() > expireTime) {
            return { status: 403, message: 'Token Expired!' };
        }

        if (domainUse !== domain) {
            return {
                status: 401,
                message: `Unauthorized Domain: ${domain}!`
            };
        }

        const expectedHash = crypto.createHash('sha256')
            .update(domainUse + uuid + expireTime + secretKey)
            .digest('hex');

        if (expectedHash !== tokenHex) {
            return { status: 500, message: 'Invalid Token!' };
        }

        return {
            status: 200,
            message: 'Token Verification Success.',
        };

    } catch (err) {
        return { status: 500, message: 'Token Verification Failed!' };
    }
}

function deriveKey(secret) {
    return crypto.createHash(HASH_ALGORITHM).update(secret).digest();
}

function getJwtSecret() {
    return crypto.randomBytes(32).toString('hex');
}

function getRefreshSecret() {
    return crypto.randomBytes(32).toString('hex');
}

function getApiSecret() {
    return crypto.randomBytes(16).toString('hex');
}

function generateJwtToken(user, jwtSecret = null, refreshSecret = null) {
    if (!user || !user.id) {
        return { status: 401, message: 'Invalid user provided!' };
    }

    const JWT_SECRET = jwtSecret || process.env.JWT_SECRET;
    const REFRESH_SECRET = refreshSecret || process.env.REFRESH_SECRET;

    if (!JWT_SECRET || !REFRESH_SECRET) {
        return { status: 401, message: 'JWT_SECRET and REFRESH_SECRET must be configured!' };
    }

    const accessToken = jwt.sign(
        {
            userId: user.id,
            username: user.username,
            role: user.role || 'user',
            type: 'access'
        },
        JWT_SECRET,
        { expiresIn: '15m' }
    );

    const refreshToken = jwt.sign(
        { 
            userId: user.id,
            type: 'refresh',
            version: user.tokenVersion || 1
        },
        REFRESH_SECRET,
        { expiresIn: '7d' }
    );

    return {
        status: 200,
        tokens: { accessToken, refreshToken }
    };
}

function verifyJwtToken(token, secret) {
    if (!token) {
        return { status: 401, message: 'Invalid token provided!' };
    }

    if (!secret) {
        return { status: 401, message: 'Invalid secret provided!' };
    }
    
    try {
        const decoded = jwt.verify(token, secret);
        return { status: 200, message: 'JWT verified.', decoded };
    } catch (err) {
        if (err.name === 'TokenExpiredError') {
            return { status: 403, message: 'Token expired!', expired: true };
        }

        return { status: 401, message: 'Invalid token!' };
    }
}

const AuthHandler = {
    getUniqueId,
    encrypt,
    decrypt,
    generateApiToken,
    verifyApiToken,
    getJwtSecret,
    getRefreshSecret,
    getApiSecret,
    generateJwtToken,
    verifyJwtToken
}

export default AuthHandler;
